"""Enumerate and classify the good-manifold count a(n)."""
from typing import List

HEAD = {1: 6, 2: 8, 3: 12, 4: 24, 5: 40, 6: 80}


def good_count(n: int) -> int:
    """a(n): exceptional head for n<=6, then 2^n on the tail."""
    return HEAD.get(n, 2 ** n)


def classify(n: int) -> str:
    return "head (exceptional)" if n in HEAD else "tail (2^n)"


def main() -> None:
    for n in range(1, 15):
        print(f"a({n:2d}) = {good_count(n):6d}   [{classify(n)}]")


if __name__ == "__main__":
    main()

"""Verify the telescoping tail-sum identity sum_{k=7}^N a(k) = 2^(N+1) - 2^7."""
from typing import List

HEAD = {1: 6, 2: 8, 3: 12, 4: 24, 5: 40, 6: 80}


def good_count(n: int) -> int:
    return HEAD.get(n, 2 ** n)


def direct_sum(N: int) -> int:
    return sum(good_count(k) for k in range(7, N + 1))


def closed_sum(N: int) -> int:
    return 2 ** (N + 1) - 2 ** 7


def main() -> None:
    for N in range(7, 20):
        d, c = direct_sum(N), closed_sum(N)
        assert d == c, (N, d, c)
        print(f"N={N:2d}: sum={d:8d} = 2^{N+1}-2^7 = {c:8d}  OK")


if __name__ == "__main__":
    main()

"""Contrast exponential a(n)=2^n (tail) with super-exponential n!."""
from math import factorial
from typing import Callable

HEAD = {1: 6, 2: 8, 3: 12, 4: 24, 5: 40, 6: 80}


def good_count(n: int) -> int:
    return HEAD.get(n, 2 ** n)


def eventually_beats(f: Callable[[int], int], c: int, horizon: int) -> bool:
    for cutoff in range(horizon):
        if all(f(n) > c ** n for n in range(cutoff, horizon)):
            return True
    return False


def main() -> None:
    H = 40
    print("a(n) beats 3^n eventually? ", eventually_beats(good_count, 3, H))
    print("n!   beats 3^n eventually? ", eventually_beats(factorial, 3, H))
    print("=> a(n) is exponential (2^n), NOT super-exponential; n! is.")


if __name__ == "__main__":
    main()

